```python
from flask import Flask, render_template, request, redirect, url_for

app = Flask(__name__)

# Criação de credenciais fake
def generate_fake_credentials():
    return {
        'username': 'user123',
        'password': 'senha123'
    }

# Rotina de login falsa
@app.route('/login', methods=['POST', 'GET'])
def login():
    if request.method == 'GET':
        return render_template('login.html')

    username, password = request.form.get('username'), request.form.get('password')

    fake_credentials = generate_fake_credentials()

    if username == fake_credentials['username'] and password == fake_credentials['password']:
        return redirect(url_for('success_page'))
    else:
        return "Login falhou. Acesso bloqueado."

# Rotina de sucesso
@app.route('/success_page')
def success_page():
    return "Você logou com sucesso!"

# Rotina de erro
@app.route('/error_page')
def error_page():
    return "Erro no login. Tente novamente."

# Inclui o template
@app.route('/')
def index():
    return render_template('index.html')

# Inicia o servidor
if __name__ == '__main__':
    app.run(debug=True)
```

